(()=>{
function standardize(root=document){const buttons=[...(root.matches?.('button')?[root]:[]),...root.querySelectorAll('button')];for(const button of buttons)if(/^(salvar(?:\s+.*)?|cancelar)$/i.test(button.textContent.trim()))button.classList.add('standard-form-action')}
standardize();new MutationObserver(records=>{for(const r of records){if(r.type==='characterData'){const b=r.target.parentElement?.closest('button');if(b)standardize(b)}else for(const node of r.addedNodes)if(node.nodeType===1)standardize(node)}}).observe(document.body,{childList:true,subtree:true,characterData:true});
})();

(()=>{
function unify(){document.querySelectorAll('.shortcut-actions,.side-controls,.fee-header-actions').forEach(host=>{const buttons=[...host.children].filter(e=>e.tagName==='BUTTON'&&e.id!=='toggleMenu'&&!e.classList.contains('menu-layout-toggle')&&e.dataset.navigationControl!=='menu'&&!e.classList.contains('menu-search-toggle'));const expand=buttons.find(b=>/^Expandir /i.test(b.getAttribute('aria-label')||b.title||''));const collapse=buttons.find(b=>/^Recolher /i.test(b.getAttribute('aria-label')||b.title||''));if(!expand||!collapse)return;let expanded=false;const toggle=document.createElement('button');toggle.type='button';toggle.className=expand.className+' unified-expand-toggle';function update(){const label=expanded?(collapse.getAttribute('aria-label')||collapse.title):(expand.getAttribute('aria-label')||expand.title);toggle.title=label;toggle.setAttribute('aria-label',label);toggle.setAttribute('aria-expanded',String(expanded));toggle.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 10 7-7 7 7M5 14l7 7 7-7"/></svg>'}toggle.onclick=e=>{e.preventDefault();if(host.classList.contains('side-controls')){const sections=[...document.querySelectorAll('.sidebar-section-toggle')],menus=[...document.querySelectorAll('.nav-tree details')];if(!expanded){if(sections.some(b=>b.getAttribute('aria-expanded')==='false')){sections.filter(b=>b.getAttribute('aria-expanded')==='false').forEach(b=>b.click());expanded=false}else{expand.click();expanded=true}}else if(menus.some(d=>d.open)){collapse.click();expanded=true}else{sections.filter(b=>b.getAttribute('aria-expanded')==='true').forEach(b=>b.click());expanded=false}update();return}expanded?collapse.click():expand.click();expanded=!expanded;update()};expand.before(toggle);expand.remove();collapse.remove();update()})}
let queued=false;const schedule=()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;unify()})};new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});unify();
})();
